#!/usr/bin/env python3
"""Permanent offline CLI regression. All inputs here are artificial, not regulatory facts."""
import csv, hashlib, io, json, pathlib, subprocess, sys, tempfile, unittest
P=pathlib.Path(__file__).resolve().parent
sha=lambda b:hashlib.sha256(b).hexdigest()
contract=json.loads((P/'catalog-source-contract-r03.json').read_text())
C='TA_CONSULTA_MEDICAMENTOS.CSV'; PR='TA_PRECOS_MEDICAMENTOS.csv'; R='TA_RESTRICAO_MEDICAMENTO.csv'
def encode_row(header,values):
 f=io.StringIO(newline='');csv.writer(f,delimiter=';',lineterminator='\r\n').writerow([values.get(k,'') for k in header]);return f.getvalue()
def fixture(root):
 raw=root/'raw sources';raw.mkdir();manifest={'status':'COMPLETE','supplementalStatus':'COMPLETE','sources':[]}
 for n,c in contract['sources'].items():
  h=c['header']; data=b'NOT AN OFFICIAL DOCUMENT: synthetic fixture\n'
  if h:
   header=';'.join(h)+'\r\n'
   if n==C:
    fields={'CO_SEQ_PRODUTO':'10','NO_PRODUTO':'TESTE','NU_REGISTRO_PRODUTO':'123','NO_RAZAO_SOCIAL_EMPRESA':'FAB','VALIDADE_SITUACAO':'Ativo','CO_SUBSTANCIA':'11','SUBSTANCIAS_MEDICAMENTOS':'SUB A','DS_REFERENCIA':'MARKER'}
    line=encode_row(h,fields).replace('MARKER','"A "B""')
   elif n==PR:
    line=encode_row(h,{'NU_REGISTRO':'123','DS_APRESENTACAO':'MARKER','CO_GGREM':'1','NO_PRODUTO':'TESTE','DS_SUBSTANCIA':'SUB A'}).replace('MARKER','"F" 10 MG COM')
   else:line=encode_row(h,{'NO_PRODUTO':'TESTE','DS_CONCENTRACAO':'MARKER','NO_PRINCIPIO_ATIVO':'SUB A'}).replace('MARKER','&#8805; 30')
   data=(header+line).encode('utf-8')
  (raw/n).write_bytes(data);head=b'SYNTHETIC HEADERS\n';(raw/(n+'.headers')).write_bytes(head);manifest['sources'].append({'name':n,'url':c['url'],'effectiveUrl':c['url'],'status':'DOWNLOADED','sha256':sha(data),'bytes':len(data),'headersSHA256':sha(head)})
 (raw/'SOURCE-MANIFEST.json').write_text(json.dumps(manifest));return raw
class LexicalCLI(unittest.TestCase):
 def test_proposal_cli_and_dry_run(self):
  with tempfile.TemporaryDirectory(prefix='vault lexical ') as t:
   root=pathlib.Path(t);raw=fixture(root);out=root/'review';args=[sys.executable,str(P/'propose-catalog-lexical-ledger-r03.py'),str(raw),str(out)];result=subprocess.run(args,capture_output=True,text=True);self.assertEqual(result.returncode,0,result.stdout+result.stderr)
   ledger=out/'FROZEN-LEXICAL-LEDGER.json';l=json.loads(ledger.read_text());self.assertEqual([len(x['edits']) for x in l['sources']],[1,1,1]);self.assertTrue(all(x['dualPass'] for x in l['sources']));self.assertTrue(all(x['rawSHA256']==x['reversedSHA256'] for x in l['sources']))
   # Snapshot only in synthetic files; exact hash generated by existing JS authority.
   snap=root/'snap.json';program="""const {digest}=require(process.argv[1]);const {TABLES}=require(process.argv[2]);const snapshot=Object.fromEntries(Object.keys(TABLES).map(k=>[k,[]]));snapshot.products=[{id:'p',external_id:'10',product_name:'TESTE',registration_number:'123',manufacturer:'FAB',active:true}];snapshot.substances=[{id:'s',external_id:'11',canonical_name:'SUB A',canonical_name_normalized:'sub a',active:true}];console.log(JSON.stringify({snapshot,manifest:{status:'DOUBLE_READ_MATCH',project:'gqxqbfkcgfhsqtwjlhvz',sha256:digest(snapshot),counts:Object.fromEntries(Object.entries(snapshot).map(([k,v])=>[k,v.length]))}}));"""
   snap.write_bytes(subprocess.check_output(['node','-e',program,str(P/'catalog-integrity-review-r02.cjs'),str(P/'catalog-integrity-snapshot-r01.cjs')]))
   cmd=['node',str(P/'catalog-integrity-dry-run-r01.cjs'),'--lexical-ledger-review',str(raw),str(snap),str(ledger),sha(ledger.read_bytes())];report=root/'report.json';ok=subprocess.run(cmd+[str(report)],capture_output=True,text=True);self.assertEqual(ok.returncode,0,ok.stdout+ok.stderr);r=json.loads(report.read_text());self.assertEqual(r['simulation']['addedLinks'],1);self.assertTrue(r['simulation']['idempotent']);self.assertTrue(r['simulation']['snapshotPreserved']);self.assertEqual(r['productionWrites'],0);self.assertEqual(r['publication'],'LOCKED');self.assertFalse(r['readyForPublication']);self.assertTrue(r['sourceOverlayReviewRequired']);self.assertEqual(r['sourceOverlayBindingHashEncoding'],'STABLE_JSON_UTF8');self.assertEqual(len(r['sourceOverlayBindingSHA256']),64);self.assertEqual(r['reviewPlan']['sourceVersionBinding'],'UNBOUND_UNTIL_OFFICIAL_MANIFEST_AND_GUARDIAN')
   # Reject an altered official file, a wrong ledger hash and an already-used output path.
   bad=root/'bad.json';self.assertNotEqual(subprocess.run(cmd[:-1]+['0'*64,str(bad)],capture_output=True).returncode,0);self.assertFalse(bad.exists());self.assertNotEqual(subprocess.run(cmd+[str(report)],capture_output=True).returncode,0)
   p=raw/C;p.write_bytes(p.read_bytes()+b'bad');self.assertNotEqual(subprocess.run(cmd+[str(bad)],capture_output=True).returncode,0);self.assertFalse(bad.exists())
 def test_unknown_width_rejected(self):
  with tempfile.TemporaryDirectory() as t:
   root=pathlib.Path(t);raw=fixture(root);p=raw/R;p.write_bytes(p.read_bytes().replace(b'&#8805; 30',b'UNKNOWN; 30'));m=raw/'SOURCE-MANIFEST.json';j=json.loads(m.read_text());r=next(x for x in j['sources'] if x['name']==R);r.update(sha256=sha(p.read_bytes()),bytes=p.stat().st_size);m.write_text(json.dumps(j));out=root/'review';res=subprocess.run([sys.executable,str(P/'propose-catalog-lexical-ledger-r03.py'),str(raw),str(out)],capture_output=True,text=True);self.assertEqual(res.returncode,3,res.stdout+res.stderr);l=json.loads((out/'FROZEN-LEXICAL-LEDGER.json').read_text());s=next(x for x in l['sources'] if x['name']==R);self.assertEqual(len(s['unresolved']),1);self.assertEqual(len(s['edits']),0);self.assertFalse(s.get('dualPass',False));self.assertEqual(l['publication'],'LOCKED')
if __name__=='__main__':unittest.main(verbosity=2)
